$p=new PDO('mysql:host='.$env['GPT_DB_HOST'].';port='.$env['GPT_DB_PORT'].';dbname=gatlas_dbp;charset=utf8mb4',$env['GPT_DB_USERNAME'],$env['GPT_DB_PASSWORD'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$p->exec("INSERT INTO permissoes (codperfil,codmenu,pode_incluir,pode_visualizar,pode_editar,pode_excluir,pode_exportar_excel,pode_gerar_pdf) SELECT pm.codperfil,pm.codmenu,pm.pode_incluir,pm.pode_visualizar,pm.pode_editar,pm.pode_excluir,pm.pode_exportar_excel,pm.pode_gerar_pdf FROM perfil_menus pm WHERE NOT EXISTS (SELECT 1 FROM permissoes x WHERE x.codperfil=pm.codperfil AND x.codmenu=pm.codmenu)");$n=(int)$p->query('SELECT COUNT(*) FROM permissoes')->fetchColumn();$s=$p->prepare("INSERT INTO registros_migracao (codigo_migracao,origem,destino,tipo,versao,status,quantidade_registros,iniciada_em,concluida_em,detalhes) VALUES ('ATLAS_PERMISSOES_SINCRONIZADAS','gmodelo_dbp.perfil_menus','gatlas_dbp.permissoes','ESTRUTURA','0.160.0','CONCLUIDA',?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,?) ON DUPLICATE KEY UPDATE status='CONCLUIDA',quantidade_registros=VALUES(quantidade_registros),concluida_em=CURRENT_TIMESTAMP,detalhes=VALUES(detalhes)");$s->execute([$n,json_encode(['origem'=>'perfil_menus','destino'=>'permissoes'],JSON_UNESCAPED_UNICODE)]);echo json_encode(['permissions'=>$n],JSON_UNESCAPED_UNICODE).PHP_EOL;
